/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::TransferOrderPickinglist)]
internal final class METTMSEngineTransferOrderProccess_Pickinglist extends METTMSEngineOrderProccess
{    
    METInventTransferTableExt metInventTransferTable;

}

Method.Source:
/// <summary>
/// initialize default parameters and variables
/// </summary>
/// <param name = "_sourceRecord">source table record buffer</param>
protected void init(METTMSSourceRecordHeaderMap _sourceRecord)
{
    super(_sourceRecord);
    metInventTransferTable = headerContract.getExtensionTable();
}

/// <summary>
/// Gets the execution mode of the process class
/// </summary>
/// <returns><c>METTMSEngineExecutionMode</c></returns>
protected METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = metInventTransferTable.RouteIdentifier;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METTMSEngineExecutionMode getExecutionMode()
{
    METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::TransferOrderPickinglist;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = metInventTransferTable.RouteStopIdentifier;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = metInventTransferTable.StagingLane;

    return ret;
}

/// <summary>
/// Create an instance of <c>METTMSEngineTOLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineTransferOrderProcess enum</param>
/// <param name = "_transferTable"><c>InventTransferTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineTOLinesTmpBuilder</c></returns>
METTMSEngineLinesTmpBuilder getTmpBuilderInstance(METTMSEngineExecutionMode _tmsEngineExecutionMode, METTMSSourceRecordHeaderMap _sourceRecord)
{
    return METTMSEngineLinesTmpBuilder::construct(_tmsEngineExecutionMode, _sourceRecord, '', this.parmPostingIdentifier());
}

void initTmpTable()
{
    METTMSEngineLinesTmpBuilder tmpBuilder = this.getTmpBuilderInstance(this.getExecutionMode(), headerContract.parmSourceRecord());
    proccessLinesTmp = tmpBuilder.populateTmpTable();
    hasCCR = tmpBuilder.hasCCR();
}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineTransferOrderProcessCreation", headerContract.parmSourceRecord().OrderId);
}
